// @vitest-environment node
import { describe, it, expect } from "vitest"
import { jsPDF } from "jspdf"
import { extractPdfPages, checkPdfBytes, ExtractError, MAX_PDF_BYTES } from "../lib/estimate-gap/extract"
import { parseDocument, compareEstimates } from "../lib/estimate-gap"

/**
 * SYNTHETIC TEST DATA. The PDFs below are generated by these tests with made-up estimate rows. They show the reader
 * handles files in this layout and fails safely on bad files. They do not show accuracy on real insurance estimates.
 */

type Row = [string, string, string, string, string] // description, quantity, unit, unit price, total

/** Builds a simple text-based estimate PDF, one table per page, laid out in columns */
function makePdf(pages: Row[][], opts: { encrypt?: boolean } = {}): Uint8Array {
  const doc = new jsPDF(opts.encrypt ? { encryption: { userPassword: "secret", ownerPassword: "owner" } } : {})
  pages.forEach((rows, i) => {
    if (i > 0) doc.addPage()
    doc.setFontSize(11)
    doc.text("SYNTHETIC TEST ESTIMATE", 14, 15)
    let y = 30
    for (const [desc, qty, unit, price, total] of rows) {
      doc.text(desc, 14, y)
      doc.text(qty, 110, y)
      doc.text(unit, 130, y)
      doc.text(price, 150, y)
      doc.text(total, 175, y)
      y += 8
    }
  })
  return new Uint8Array(doc.output("arraybuffer"))
}
const blankPdf = (n: number) => { const d = new jsPDF(); for (let i = 1; i < n; i++) d.addPage(); return new Uint8Array(d.output("arraybuffer")) }

const INS: Row[] = [
  ["Tear off comp. shingles - Laminated", "25.00", "SQ", "45.00", "1,125.00"],
  ["Laminated comp. shingle rfg. w/ felt", "25.00", "SQ", "220.00", "5,500.00"],
  ["Drip edge", "180.00", "LF", "2.50", "450.00"],
]
const CON: Row[] = [
  ["Tear off comp. shingles - Laminated", "27.00", "SQ", "45.00", "1,215.00"],
  ["Laminated comp. shingle rfg. w/ felt", "25.00", "SQ", "235.00", "5,875.00"],
  ["Drip edge", "180.00", "LF", "2.50", "450.00"],
  ["Ice & water shield", "600.00", "SF", "1.85", "1,110.00"],
]

describe("reading a text-based PDF", () => {
  it("returns each page's rows in reading order with the page number", async () => {
    const { pages, pageCount } = await extractPdfPages(makePdf([INS, [INS[0]]]))
    expect(pageCount).toBe(2)
    expect(pages.map((p) => p.page)).toEqual([1, 2])
    const lines = pages[0].text.split("\n")
    expect(lines[0]).toContain("SYNTHETIC TEST ESTIMATE")
    expect(lines[1]).toMatch(/Tear off comp\. shingles - Laminated\s+25\.00\s+SQ\s+45\.00\s+1,125\.00/)
    expect(pages[1].text).toContain("1,125.00")
  })
  it("feeds the comparison engine end to end: real PDFs in, evidence with page numbers out", async () => {
    const ins = await extractPdfPages(makePdf([INS]))
    const con = await extractPdfPages(makePdf([CON]))
    const result = compareEstimates(parseDocument("insurer", ins.pages), parseDocument("contractor", con.pages))
    expect(result.canCompare).toBe(true)
    const qty = result.findings.find((f) => f.kind === "quantity_difference")!
    expect(qty.numbers).toMatchObject({ insurerQuantity: "25", contractorQuantity: "27" })
    expect(qty.evidence.every((e) => e.page === 1 && e.raw.includes("Tear off"))).toBe(true)
    expect(result.findings.find((f) => f.kind === "unit_price_difference")!.numbers).toMatchObject({ insurerUnitPrice: "$220.00", contractorUnitPrice: "$235.00" })
    expect(result.findings.find((f) => f.kind === "line_only_on_contractor_estimate")!.evidence[0].raw).toContain("Ice & water shield")
  })
  it("reports the right page for a row on page 2", async () => {
    const { pages } = await extractPdfPages(makePdf([[INS[0]], [INS[2]]]))
    const doc = parseDocument("insurer", pages)
    expect(doc.lines.map((l) => [l.page, l.description])).toEqual([[1, "Tear off comp. shingles - Laminated"], [2, "Drip edge"]])
  })
})

describe("files it cannot or should not read", () => {
  const code = async (data: Uint8Array) => { try { await extractPdfPages(data); return "read" } catch (e) { return e instanceof ExtractError ? e.code : "other:" + String(e) } }

  it("refuses a file that is not a PDF, whatever it is named", async () => {
    expect(await code(new TextEncoder().encode("<html><script>alert(1)</script></html>"))).toBe("not_a_pdf")
    expect(await code(new Uint8Array([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a]))).toBe("not_a_pdf")
  })
  it("refuses an empty file and one that is too large", async () => {
    expect(await code(new Uint8Array(0))).toBe("empty")
    const big = new Uint8Array(MAX_PDF_BYTES + 1)
    big.set(new TextEncoder().encode("%PDF-1.4"))
    expect(await code(big)).toBe("too_large")
    expect(() => checkPdfBytes(big)).toThrow(/4 MB/)
  })
  it("refuses a password-protected PDF with a clear message", async () => {
    const e = await extractPdfPages(makePdf([INS], { encrypt: true })).catch((x) => x)
    expect(e).toBeInstanceOf(ExtractError)
    expect(e.code).toBe("password_protected")
    expect(e.message).toMatch(/password/)
  })
  it("refuses a damaged PDF instead of returning made-up text", async () => {
    const good = makePdf([INS])
    expect(["damaged", "unreadable"]).toContain(await code(good.slice(0, 200)))
    const header = new TextEncoder().encode("%PDF-1.4\nthis is not really a pdf body")
    expect(["damaged", "unreadable"]).toContain(await code(header))
  })
  it("refuses a PDF with too many pages", async () => {
    expect(await code(blankPdf(61))).toBe("too_many_pages")
  })
  it("reports a page with no text (like a scan) as empty instead of guessing", async () => {
    const { pages } = await extractPdfPages(blankPdf(2))
    expect(pages.map((p) => p.text)).toEqual(["", ""])
    const doc = parseDocument("insurer", pages)
    expect(doc.pagesWithoutText).toEqual([1, 2])
    const result = compareEstimates(doc, parseDocument("contractor", (await extractPdfPages(makePdf([CON]))).pages))
    expect(result.canCompare).toBe(false)
    expect(result.blockingReasons.join(" ")).toMatch(/insurance estimate/)
  })
  it("does not change the bytes it was given", async () => {
    const data = makePdf([INS])
    const before = Array.from(data.slice(0, 64)).join(",")
    await extractPdfPages(data)
    expect(Array.from(data.slice(0, 64)).join(",")).toBe(before)
  })
})
